insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0006-0000-4000-8000-000000000004', 'en', null, 'Foundations of Visual Art', 'A practical first course in how pictures work: the elements of art, the principles of design, color theory, drawing, light, composition, media, and how to read an artwork. Structure and terminology are adapted from Wikipedia, the free encyclopedia (CC BY-SA 4.0), then rewritten as hands-on lessons you can apply with pencil, paint, or pixels.', null, 'foundations', 63, true, 'arts', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0006-0000-4000-8000-000000000004', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: how do you see?', 'quiz', '{"questions":[{"prompt":"Which of these is an element of art rather than a principle of design?","options":["balance","contrast","value","rhythm"],"answer":2,"explanation":"Value (lightness/darkness) is a basic element; balance, contrast, and rhythm are principles that arrange the elements."},{"prompt":"On a standard color wheel, the three primary colors of pigment are…","options":["red, green, blue","red, yellow, blue","cyan, magenta, yellow","orange, green, violet"],"answer":1,"explanation":"In traditional pigment theory the primaries are red, yellow, and blue; mixing them yields the secondaries orange, green, and violet."},{"prompt":"The imaginary line where the ground appears to meet the sky, used to set up perspective, is the…","options":["vanishing point","horizon line","picture plane","orthogonal"],"answer":1,"explanation":"The horizon line sits at the viewer''s eye level; vanishing points live on it."},{"prompt":"Saturation refers to a color''s…","options":["lightness or darkness","temperature","intensity or purity","name on the wheel"],"answer":2,"explanation":"Saturation is how vivid or dull a color is; lightness is value and the name is hue."},{"prompt":"In the four-step critique method, the step that comes first is…","options":["judge","interpret","describe","analyze"],"answer":2,"explanation":"You describe what is literally present before analyzing, interpreting meaning, or judging quality."},{"prompt":"A shadow that an object throws onto a nearby surface is called a…","options":["core shadow","form shadow","cast shadow","highlight"],"answer":2,"explanation":"The cast shadow is projected onto another surface; the form shadow is the dark side of the object itself."},{"prompt":"Which composition guideline divides the frame into thirds and places interest near the crossings?","options":["golden spiral","rule of thirds","central symmetry","color harmony"],"answer":1,"explanation":"The rule of thirds is a simple grid that keeps focal points off dead center."},{"prompt":"Carving a figure out of a block of stone is an example of which sculptural approach?","options":["additive","subtractive","casting","modeling"],"answer":1,"explanation":"Subtractive sculpture removes material; additive methods such as modeling and casting build form up."}]}'::jsonb, null, 10),
  (2, 'The elements of art', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the seven building blocks that every visual artwork is made from and point to each one in a real image. By the end you can look at any drawing, photo, or painting and break it down into line, shape, form, value, space, color, and texture, instead of reacting to it as one undivided impression. Warm-up: from the diagnostic, which of these words names a basic element and which names a way of arranging elements: value, balance?"},{"heading":"The idea","text":"Artists describe pictures with a small shared vocabulary. Line is a moving point: it can be thick, thin, straight, curved, or implied by a row of objects. Shape is a flat enclosed area, either geometric (circle, square) or organic (a leaf). Form is shape made to look three dimensional through shading, so a circle reads as a sphere. Value is the lightness or darkness of a tone, independent of color; a good value plan lets a black-and-white photo of the work still read clearly. Space is the sense of depth and the arrangement of positive objects against negative emptiness. Color is light reflected at different wavelengths, with its own three properties you will study soon. Texture is surface quality, real (rough paper) or implied (painted fur). These seven are the raw material of everything else."},{"heading":"Worked examples / how to","text":"Take a simple still life of an apple on a table. Line: the contour that traces the apple''s edge, plus the horizontal line where the table meets the wall. Shape: the rounded silhouette seen flat, the rectangle of the tabletop. Form: the shading that turns that flat silhouette into a solid ball with a light side and a dark side. Value: squint until detail disappears and only a bright patch, a mid gray, and a dark shadow remain. Space: the apple is the positive shape; the air around it is negative space, and overlap tells you the apple sits in front of the wall. Color: a red hue, lighter near the light, duller in shadow. Texture: a waxy sheen implied by a crisp highlight. Naming each element one at a time is how trained artists diagnose why a picture does or does not work."},{"heading":"Your turn","text":"1) Is a row of trees receding into the distance an example of actual line or implied line? 2) A cube drawn with shading to look solid demonstrates which element? 3) Name the element that stays meaningful even in a grayscale photo. 4) The empty area around a subject is called what kind of space? 5) Painted bark that looks rough but feels smooth is real or implied texture? Answers: 1) implied line, because the eye connects separate trees into a line. 2) form. 3) value. 4) negative space. 5) implied texture."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing shape and form; shape is flat, form reads as solid once you add value. Mistake: ignoring value and chasing color first, which flattens a picture because value does most of the work of depth and legibility. Practice reading value before you reach for hue. Exit: (a) Which element turns a circle into a sphere? (b) Which element is about surface quality, real or implied? Answers: form (through shading); texture."}]}'::jsonb, 'Elements are the nouns of a picture (line, shape, color); principles are the verbs that arrange them (balance, rhythm). Keep the two lists separate when you talk about work.', 13),
  (3, 'The principles of design', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use seven principles to arrange the elements into a composition that feels deliberate rather than accidental: balance, contrast, emphasis, movement, pattern, rhythm, and unity. You will be able to look at a layout and say which principle is carrying it and which one is missing. Warm-up: in the diagnostic you met balance, contrast, and rhythm as principles, not elements. Can you say in one sentence what each of those three does to a picture?"},{"heading":"The idea","text":"If elements are the ingredients, principles are the recipe. Balance is the distribution of visual weight; it can be symmetrical (mirror-even), asymmetrical (different objects that still feel settled), or radial (spreading from a center). Contrast is difference set side by side, in value, color, size, or shape, and it creates energy and separation. Emphasis gives the eye a clear place to land first, the focal point. Movement is the path the eye follows through the work, often along lines or edges. Pattern is a repeated motif; rhythm is pattern with a sense of timing, where repetition and spacing create a beat. Unity is the overall sense that every part belongs to the same whole, usually achieved by repeating a color, shape, or texture. Good design balances variety (enough contrast to stay interesting) against unity (enough repetition to stay coherent)."},{"heading":"Worked examples / how to","text":"Picture a poster. Emphasis: a large bright title in the upper third grabs the eye first because it contrasts in size and value with everything else. Movement: a diagonal photograph then leads the eye down to a small call to action at the lower right. Balance: the heavy title at top is offset by a block of dark text at the bottom, asymmetrical but settled. Pattern and rhythm: three evenly spaced icons form a steady beat across the middle, and nudging their spacing wider then narrower would create syncopated rhythm. Unity: one accent color reappears in the title, an icon, and the button, tying the parts together. To test any design, ask the four questions in order: Where does my eye go first? Where does it travel? Does the weight feel settled? Does everything look like it belongs? A weak answer to any one names the principle to fix."},{"heading":"Your turn","text":"1) A layout where the left and right halves mirror each other shows which type of balance? 2) Which principle creates a clear first stop for the eye? 3) Repeating a motif with deliberate spacing and timing is pattern or rhythm? 4) Placing a tiny dark shape against a large pale field uses which principle to make it pop? 5) Which principle makes separate parts feel like one work? Answers: 1) symmetrical balance. 2) emphasis. 3) rhythm. 4) contrast. 5) unity."},{"heading":"Common mistakes & exit ticket","text":"Mistake: giving a piece two or three equally loud focal points, so emphasis cancels out and the eye has nowhere to rest; choose one dominant area. Mistake: so much variety that unity collapses into visual noise; repeat at least one element to tie things together. Exit: (a) Name the three kinds of balance. (b) What is the difference between pattern and rhythm? Answers: symmetrical, asymmetrical, radial; pattern is plain repetition, rhythm adds timing and spacing so the repetition has a beat."}]}'::jsonb, 'Emphasis answers where the eye goes first; movement answers where it travels next. If you cannot name the focal point, the composition has no emphasis yet.', 14),
  (4, 'Color theory in practice', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read the color wheel, describe any color using hue, value, and saturation, and choose a color scheme on purpose instead of by guesswork. You will be able to mix a believable shadow color and explain why a given palette feels calm or jarring. Warm-up: the diagnostic asked for the three pigment primaries. List them, then name the three secondaries you get by mixing pairs of them."},{"heading":"The idea","text":"The traditional color wheel starts with three primaries (red, yellow, blue) that cannot be mixed from others. Mixing adjacent primaries gives the secondaries: orange, green, violet. Mixing a primary with its neighboring secondary gives six tertiaries such as red-orange. Every color has three properties. Hue is the name and position on the wheel. Value is how light or dark it is; adding white makes a tint, adding black makes a shade. Saturation is purity; a fully saturated color is vivid, and mixing in its opposite dulls it toward gray. Colors opposite each other are complementary (red and green); neighbors are analogous (blue, blue-green, green); three evenly spaced colors form a triad. Warm hues (reds, oranges, yellows) tend to advance toward the viewer; cool hues (blues, greens, violets) tend to recede."},{"heading":"Worked examples / how to","text":"Scheme choices carry mood. A monochromatic scheme uses one hue at several values and saturations and feels unified and quiet. An analogous scheme (yellow, yellow-green, green) feels harmonious and natural. A complementary scheme (orange and blue) is high energy because the opposites intensify each other where they meet, which is why film posters lean on orange-and-teal. To mix a convincing shadow, do not just add black, which deadens the hue; instead lower the value and nudge the hue toward the complement, so a red apple''s shadow leans slightly green-gray and stays alive. To calm a color that is too loud, add a touch of its complement to drop saturation without darkening it much. Try arranging five objects by value first, ignoring their hues, to prove that value, not color, is doing the heavy lifting of depth."},{"heading":"Your turn","text":"1) What do you call red plus white? 2) Which property changes when you move from vivid red to dull grayish red at the same lightness? 3) Name the complement of blue on the traditional wheel. 4) Yellow, yellow-orange, and orange form what kind of scheme? 5) Do warm colors tend to advance or recede? Answers: 1) a tint. 2) saturation. 3) orange. 4) analogous. 5) advance."},{"heading":"Common mistakes & exit ticket","text":"Mistake: darkening every color with pure black, which muddies the hue and kills the sense of light; lower value by mixing toward the complement or a darker related hue instead. Mistake: treating saturation and value as the same dial; a color can be dark yet vivid, or light yet dull. Exit: (a) Which two properties besides hue describe a color? (b) What is a reliable way to dull a color without darkening it? Answers: value and saturation; add a small amount of its complementary color."}]}'::jsonb, 'Every color has three dials: hue (which color), value (how light), and saturation (how pure). To change a color precisely, say which dial you are turning.', 14),
  (5, 'Checkpoint 1: seeing and arranging', 'quiz', '{"questions":[{"prompt":"A flat circle becomes a convincing sphere once you add…","options":["more line","value shading","a second circle","brighter hue"],"answer":1,"explanation":"Value shading turns the shape into form by describing the light and dark sides."},{"prompt":"The empty area surrounding a subject is called…","options":["positive space","negative space","picture plane","the focal point"],"answer":1,"explanation":"Negative space is the air around the positive shapes and is part of the composition."},{"prompt":"Which principle decides where the eye lands first?","options":["unity","pattern","emphasis","balance"],"answer":2,"explanation":"Emphasis creates the dominant focal point."},{"prompt":"Red and green sit opposite each other, making them…","options":["analogous","complementary","monochromatic","tertiary"],"answer":1,"explanation":"Colors opposite on the wheel are complementary and intensify each other."},{"prompt":"Adding black to a hue produces a…","options":["tint","shade","triad","highlight"],"answer":1,"explanation":"A shade is a hue plus black; a tint is a hue plus white."},{"prompt":"A composition with mirror-even halves demonstrates…","options":["radial balance","asymmetrical balance","symmetrical balance","rhythm"],"answer":2,"explanation":"Symmetrical balance mirrors visual weight across an axis."}]}'::jsonb, null, 8),
  (6, 'Drawing fundamentals: observation, proportion, perspective', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Draw what you actually see rather than what you assume, keep proportions accurate by measuring, and set up believable depth with one-point and two-point perspective. You will be able to block in a scene using a horizon line and vanishing points instead of guessing at angles. Warm-up: from the diagnostic, what is the name of the eye-level line that every perspective drawing is built on?"},{"heading":"The idea","text":"Observational drawing starts by seeing shapes, angles, and relationships instead of symbols. Beginners draw the idea of an eye; trained artists draw the specific tilted almond in front of them. Proportion is the size relationship between parts. A common tool is sight-size measuring: hold a pencil at arm''s length, line its tip with one end of a form, mark where the other end falls with your thumb, and carry that unit across the drawing to compare, for example, how many head-heights tall a figure is (roughly seven to eight). Perspective is how parallel lines appear to converge with distance. In one-point perspective, lines running away from you meet at a single vanishing point on the horizon, good for a hallway seen head-on. In two-point perspective, a box turned at an angle has two sets of receding lines meeting at two vanishing points on the same horizon line, good for a building corner."},{"heading":"Worked examples / how to","text":"Draw a cube in one-point perspective. First lightly rule a horizon line at eye level and mark one vanishing point on it. Draw a square for the front face. From each of its four corners, draw a faint line back to the vanishing point. Decide the depth, draw a smaller square where those lines reach it, and you have a believable box; erase the guide lines. Now turn the cube: in two-point perspective, place two vanishing points far apart on the horizon, draw a single vertical edge for the nearest corner, and send lines from its top and bottom to each vanishing point. The vertical edges stay vertical; only the horizontal edges recede. For proportion practice, draw a mug by measuring its height in widths first, then committing the outline, so the handle and rim land in the right places."},{"heading":"Your turn","text":"1) A hallway drawn straight on, with edges meeting at one point, uses how many vanishing points? 2) At what height on the page do vanishing points sit? 3) In sight-size measuring, what do you use as your fixed unit? 4) A building corner seen at an angle usually needs how many vanishing points? 5) Roughly how many head-heights tall is a standard adult figure? Answers: 1) one. 2) on the horizon line, at the viewer''s eye level. 3) one measured length, such as a head height, carried across the drawing. 4) two. 5) about seven to eight."},{"heading":"Common mistakes & exit ticket","text":"Mistake: drawing a symbol for an object (a lollipop tree, an almond eye) instead of measuring the real thing. Mistake: putting vanishing points off at random heights; both must sit on the same horizon line or the scene tilts. Mistake: making vertical edges converge in two-point perspective; keep them vertical. Exit: (a) Where do all vanishing points for a flat-ground scene lie? (b) Which perspective suits a box viewed straight on versus one turned at an angle? Answers: on the horizon line at eye level; one-point for straight on, two-point for the turned box."}]}'::jsonb, 'Measure before you commit a line. One confident measured mark beats ten hopeful erased ones.', 15),
  (7, 'Light, shadow, and rendering form', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Render a flat shape into a solid-looking form by placing light and shadow correctly, and name the parts of light on a rounded object. You will be able to shade a sphere so it reads as three dimensional and sits on its surface. Warm-up: the diagnostic distinguished a cast shadow from a form shadow. Say in one sentence how they differ."},{"heading":"The idea","text":"A single light source carves predictable zones on a rounded form. Moving from the light around to the dark, the main zones are: the highlight, the brightest spot where light reflects most directly; the halftone, the gradual mid gray as the surface turns; the core shadow, the darkest band on the object where the surface turns fully away from the light; reflected light, a faint lift inside the shadow bounced from nearby surfaces; and the cast shadow, thrown onto the ground, darkest and crispest right where the object touches down. Note that the core shadow is often darker than the cast shadow''s outer edge, and that reflected light must stay darker than any lit halftone, or the form looks hollow. Rendering is simply controlling these values so the eye reconstructs a solid object from flat marks."},{"heading":"Worked examples / how to","text":"Shade a sphere lit from the upper left. Leave a small clean highlight at the upper left. Let the tone deepen smoothly across the halftones toward the lower right. Place the core shadow as a curved band just before the far edge, not at the very edge, because a sliver of reflected light lifts the rim. Under the sphere, lay the cast shadow stretching to the lower right, darkest and sharpest where the sphere meets the surface and softer and lighter as it extends away. Finally check the value order from lightest to darkest: highlight, light halftone, dark halftone, reflected light, cast shadow, core shadow. If your reflected light is brighter than your halftones, knock it down. The same five zones apply to a face, an apple, or a column; only the surface curvature changes where the bands fall."},{"heading":"Your turn","text":"1) Which zone is the single brightest point on a lit form? 2) The darkest band on the object itself is called the…? 3) Where is a cast shadow darkest and sharpest? 4) Reflected light should be lighter or darker than the lit halftones? 5) The core shadow usually sits at the very edge or just inside it? Answers: 1) the highlight. 2) core shadow. 3) right where the object touches the surface. 4) darker. 5) just inside the edge, leaving room for reflected light along the rim."},{"heading":"Common mistakes & exit ticket","text":"Mistake: outlining a shape and filling the whole shadow side with one flat gray, which reads as a cut-out, not a form; use a gradient through the halftones. Mistake: making reflected light too bright, which punches a hole in the form. Mistake: forgetting the cast shadow, so the object floats. Exit: (a) List the five light zones from lightest to darkest. (b) Why keep reflected light dimmer than the halftones? Answers: highlight, halftone, reflected light, cast shadow, core shadow (reflected light sitting between cast and core); because brighter reflected light would flatten the turn of the form."}]}'::jsonb, 'Name the shadow before you darken it. Core shadow, cast shadow, and reflected light are different values and mixing them up flattens the form.', 14),
  (8, 'Composition: arranging the whole frame', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Plan where things go inside the frame so the picture guides the viewer''s eye on purpose. You will be able to place a focal point, use leading lines, balance the frame, and use negative space, judging a layout before investing hours in detail. Warm-up: from the diagnostic, which guideline divides the frame into thirds and places interest near the grid crossings?"},{"heading":"The idea","text":"Composition is the arrangement of elements within the borders of the work. The rule of thirds divides the frame with two horizontal and two vertical lines and places key subjects along those lines or at their four intersections, which feels livelier than dead center. Leading lines are real or implied lines (a road, a gaze, a fence) that carry the eye toward the focal point. Balance distributes visual weight across the frame so it does not feel lopsided. Negative space, the empty area, is an active ingredient: generous empty space can isolate and emphasize a small subject. The focal point is the one spot you most want seen, created through contrast, placement, or convergence of lines. Related tools include framing (using foreground shapes to enclose the subject) and the golden ratio, an off-center proportion close to the rule-of-thirds idea."},{"heading":"Worked examples / how to","text":"Compose a landscape photo of a lone tree. Instead of centering the horizon, place it on the lower third so the sky dominates, then put the tree on the right vertical third line rather than the middle. A path curving in from the lower left becomes a leading line that walks the eye up to the tree, the focal point. The large calm sky is negative space that makes the single tree feel significant. To test balance, imagine the frame as a scale: the heavy tree on the right is offset by the implied weight of the open path on the left. Before rendering, do three tiny thumbnail sketches, each an inch wide, trying the subject in different thirds; choosing the strongest arrangement at thumbnail size saves you from fixing a weak layout after hours of detail."},{"heading":"Your turn","text":"1) Where does the rule of thirds suggest placing a key subject? 2) A winding road that draws the eye to a mountain is acting as what? 3) The empty sky that makes a small subject stand out is which kind of space? 4) Name one quick way to test a composition before committing. 5) The single spot you most want the viewer to notice is the…? Answers: 1) along a third line or at a grid intersection, not dead center. 2) a leading line. 3) negative space. 4) small thumbnail sketches. 5) focal point."},{"heading":"Common mistakes & exit ticket","text":"Mistake: centering everything, which can feel static unless symmetry is the point. Mistake: a horizon line splitting the frame exactly in half, which divides attention; favor the upper or lower third. Mistake: so many competing details that no focal point wins. Exit: (a) What does a leading line do? (b) Why avoid placing the horizon in the exact middle? Answers: it directs the eye toward the focal point; because an even split halves the emphasis instead of favoring either sky or ground."}]}'::jsonb, 'A focal point is where you want the eye; a leading line is the road that takes it there. Plan both before you render detail.', 13),
  (9, 'Media and techniques', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize the major families of art media, describe what each is good at, and pick a sensible medium for a given goal. You will be able to tell drawing from painting from printmaking from sculpture from digital work, and name a characteristic technique of each. Warm-up: the diagnostic asked about carving a figure from stone. Was that an additive or a subtractive process, and why?"},{"heading":"The idea","text":"Drawing uses dry or linear media such as graphite pencil, charcoal, and ink; it is quick, forgiving, and ideal for studies and line. Painting applies pigment suspended in a binder: watercolor is transparent and luminous but hard to correct, acrylic dries fast and is flexible, and oil stays workable for days and blends richly. Printmaking makes multiple impressions from a prepared surface: relief (carving away what stays white, as in woodcut and linocut), intaglio (incising lines that hold ink, as in etching and engraving), lithography (based on grease repelling water), and screenprinting (pushing ink through a stencil on mesh). Sculpture works in three dimensions, either subtractive (carving stone or wood away) or additive (modeling clay, assembling, or casting metal from a mold). Digital media use software and a tablet to simulate many of these while adding layers, undo, and easy duplication."},{"heading":"Worked examples / how to","text":"Suppose you want to capture a moving crowd in a cafe in ten minutes: reach for drawing, specifically charcoal or a brush pen, because speed and strong value matter more than permanence. For a glowing sunrise with soft graded skies, watercolor''s transparency shines, laying light washes first and saving the white of the paper for the brightest light. For a portrait you will revise over a week, oil lets you blend wet into wet and scrape back. To produce fifty identical event posters by hand, screenprinting is efficient once the stencil is cut. To make a small bronze figure, you model it in clay, make a mold, and cast metal, an additive route. For concept work needing endless revisions and color tests, digital layers let you try variations without starting over. The lesson: each medium has a grain, and good artists choose the tool whose strengths match the task."},{"heading":"Your turn","text":"1) Which painting medium is prized for transparent, luminous washes and is hard to correct? 2) Woodcut and linocut belong to which printmaking family? 3) Casting a bronze from a mold is additive or subtractive sculpture? 4) Which medium offers layers and unlimited undo? 5) For a fast ten-minute value study, name a suitable drawing medium. Answers: 1) watercolor. 2) relief. 3) additive. 4) digital. 5) charcoal (or a brush pen)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: fighting a medium''s nature, such as trying to make opaque corrections in transparent watercolor, or demanding instant blends from fast-drying acrylic. Mistake: assuming all printmaking is the same; relief, intaglio, lithography, and screenprint each ink the surface differently. Exit: (a) Name the two broad categories of sculpture and one example of each. (b) Which oil property makes it good for slow, blended portraits? Answers: subtractive (carving stone) and additive (modeling clay or casting); oil stays wet and workable for days, allowing smooth blending and revision."}]}'::jsonb, 'Match the medium to the goal: fast studies in graphite, luminous washes in watercolor, reworkable layers in oil. The tool shapes what the mark can do.', 13),
  (10, 'Reading art: critique and a movements survey', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Analyze and critique any artwork with a clear four-step method, and place a work roughly in the sweep of major art movements so your interpretation has context. You will be able to move past I like it toward a reasoned account of what a piece does and how well. Warm-up: from the diagnostic, which step of the critique comes first, before any interpretation of meaning?"},{"heading":"The idea","text":"A widely taught critique has four steps in order. Describe: list only what is literally present, the subject, colors, size, and media, with no opinion yet. Analyze: examine how the elements and principles are used, the value structure, the balance, the focal point, the leading lines. Interpret: propose what the work means or expresses and what evidence in the image supports that reading. Judge: evaluate how successful the work is for its apparent goals, giving reasons drawn from the earlier steps. Keeping the steps separate stops you from leaping to a verdict before you have really looked. To interpret well it helps to know the broad movements a work may belong to, since style carries meaning: a blurred open-air scene reads differently once you know the vocabulary of its period."},{"heading":"Worked examples / how to","text":"A short survey for context, roughly in time order: Renaissance art (around 1400 to 1600) sought lifelike proportion, perspective, and balanced composition. Baroque (1600s) added drama, movement, and strong light-dark contrast. Impressionism (late 1800s) chased fleeting light with loose, visible brushwork painted outdoors. Post-Impressionism pushed into structure and emotion beyond pure observation. Cubism (early 1900s) fractured objects into multiple viewpoints at once. Surrealism staged dreamlike, irrational scenes. Abstract Expressionism (mid 1900s) made the act of painting and raw gesture the subject. Pop Art drew on advertising and mass culture. Now apply the four steps to an Impressionist river scene: Describe a bright outdoor scene of a river with small dabs of color and no hard outlines. Analyze the broken brushwork, high-key value range, and warm-cool contrasts that shimmer. Interpret it as an attempt to capture a passing moment of light rather than permanent detail. Judge it as successful at conveying atmosphere, if you value mood over sharp description."},{"heading":"Your turn","text":"1) In which critique step do you list only what is literally present? 2) Which step gives a reasoned verdict on success? 3) Which movement is known for loose brushwork and capturing fleeting light outdoors? 4) Which early-1900s movement fractured objects into several viewpoints at once? 5) Where does proposing meaning belong among the steps? Answers: 1) describe. 2) judge. 3) Impressionism. 4) Cubism. 5) interpret, which comes third, after describe and analyze."},{"heading":"Common mistakes & exit ticket","text":"Mistake: smuggling judgment into the describe step (it''s beautiful) instead of neutral observation; save evaluation for the end. Mistake: interpreting with no evidence, so the reading floats free of the actual image; tie each claim to something you described or analyzed. Mistake: forcing every work into one favorite movement; many pieces blend or resist labels. Exit: (a) List the four critique steps in order. (b) Name one movement that prized capturing light outdoors and one that fractured objects into multiple views. Answers: describe, analyze, interpret, judge; Impressionism (light) and Cubism (multiple views)."}]}'::jsonb, 'Keep the four steps in order and in their lanes. Description is only what is there; save opinion for the judge step so your reasons are grounded.', 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0006-0000-4000-8000-000000000004' and l.position = v.pos
);
